L10_1.m_Talk_KOREA = "<color=#ff3636>[검열됨]</color>!! <color=#ff3636>[검열됨]</color>!! 니들은 잠도 없어!?"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "<color=#ff3636>[検閲済]</color>！！　<color=#ff3636>[検閲済]</color>！！　アンタたちは寝ないっての！？"
L10_1.m_Talk_ENG = "<color=#ff3636>[BLEEP]</color>!! <color=#ff3636>[BLEEP]</color>!! Don't you guys even SLEEP?!!"
L10_1.m_Talk_TWN = "<color=#ff3636>[嗶——]</color>！！<color=#ff3636>[嗶——]</color>！！你們都不睡覺的嗎？！"
L10_1.m_Talk_THA = "<color=#ff3636>[BLEEP]</color>!! <color=#ff3636>[BLEEP]</color>!! พวกคุณไม่หลับไม่นอนกันเหรอ?!!"
L10_1.m_Talk_VTN = "<color=#ff3636>[BLEEP]</color>!! <color=#ff3636>[BLEEP]</color>!! Mấy cậu không NGỦ sao?!!"
L10_1.m_Talk_SCN = "<color=#ff3636>[哔——]</color>！<color=#ff3636>[哔——]</color>！你们都不睡觉的吗？！"
L10_1.m_Talk_DEU = "<color=#ff3636>[PIEP]</color>!! <color=#ff3636>[PIEP]</color>!! Schlaft ihr eigentlich nie?!"
L10_1.m_Talk_FRA = "<color=#ff3636>[BIP]</color> ! <color=#ff3636>[BIP]</color> ! Vous dormez jamais ou quoi ?!"
L11_1 = {}
L11_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 31611
L11_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L11_1.m_Talk_KOREA = "기껏 연차까지 쓰고 수면보충 좀 하려는데, 꼭두새벽부터 시끄럽게 무슨 짓이야, 대체!?"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "人がせっかく有給休暇まで使って睡眠補充しようとしてるのに、朝っぱらからうるさいのよ、もう！！"
L11_1.m_Talk_ENG = "I even used my PTO to get some well-needed sleep, and you HAD to cause a ruckus this early in the morning?!"
L11_1.m_Talk_TWN = "我好不容易休假想補眠，你們大清早的到底在吵什麼？！"
L11_1.m_Talk_THA = "ฉันยังต้องการเวลาในการนอนหลับให้เพียงพอ  และคุณก็ปลุกรบกวนเวลานอนของฉันตั้งแต่เช้าตรู่แบบนี้!"
L11_1.m_Talk_VTN = "Tôi thậm chí còn dùng giờ nghỉ được trả lương để làm giấc ngủ ngon, mà cậu PHẢI gây náo loạn vào sáng sớm thế này à?!"
L11_1.m_Talk_SCN = "我好不容易请了个年假补觉，你们大清早的到底在闹腾什么啊？！"
L11_1.m_Talk_DEU = "Ich habe sogar meinen Urlaub genutzt, um mal etwas Schlaf nachzuholen, aber du musstest ja unbedingt so früh am Morgen für Aufruhr sorgen?!"
L11_1.m_Talk_FRA = "J'ai même dû utiliser un jour de congé pour pouvoir faire la grasse matinée, et voilà que vous faites un tapage pareil aux aurores !"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 31611
L12_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L12_1.m_Talk_KOREA = "어이, 어이, 진정하라구. 사이버 캣. 벌써 해가 중천이야."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "ちょっと、ちょっと、落ち着いてよ。サイバーキャット。もうお昼よ。"
L12_1.m_Talk_ENG = "Whoa, whoa. Calm down, Cyber Cat. It's already noon."
L12_1.m_Talk_TWN = "喂喂，冷靜點，賽博貓，現在都已經中午咧。"
L12_1.m_Talk_THA = "โว้ โว้ ใจเย็นๆนะแมวไซเบอร์ นี่เธอนอนกินบ้านจนเที่ยงแล้วนะ"
L12_1.m_Talk_VTN = "Ối, ôi. Bình tĩnh nào, Cyber Cat. Đã trưa rồi."
L12_1.m_Talk_SCN = "喂喂，冷静点，赛博猫。现在都已经大中午了。"
L12_1.m_Talk_DEU = "Hey, hey. Beruhige dich mal, Cyber Cat. Die Sonne ist bereits vor einer ganzen Weile aufgegangen."
L12_1.m_Talk_FRA = "Hé oh, calme-toi, Cyber Cat. Je te rappelle qu'il est déjà midi."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 31611
L13_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L13_1.m_Talk_KOREA = "일찍 일어나는 해커가 정보를 낚는 법이라고."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "早起きするハッカーこそ情報キャッチできるものよ。"
L13_1.m_Talk_ENG = "The early hacker catches the info."
L13_1.m_Talk_TWN = "俗話說早起的駭客才有情報可釣。"
L13_1.m_Talk_THA = "แฮกเกอร์รุ่นแรกจะต้องรีบคว้าข้อมูลกระฉับกระเฉงหน่อย"
L13_1.m_Talk_VTN = "Hacker sớm nhất sẽ luôn nắm bắt được thông tin."
L13_1.m_Talk_SCN = "早起的黑客才有情报可钓啊。"
L13_1.m_Talk_DEU = "Wie sagt man so schön: „Der frühe Hacker fängt die Informationen.“"
L13_1.m_Talk_FRA = "Les infos appartiennent aux hackers qui se lèvent tôt."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 31611
L14_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L14_1.m_Talk_KOREA = "앨버트 말이 옳아. 다크─세븐의 일원으로서 좀 더 자각을 가지는 게 어때, 사이버 캣?"
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "そのとおり。ダーークセブンの一員として、もっと自覚を持った方がいいんじゃないか？　サイバーキャット。"
L14_1.m_Talk_ENG = "Albert's right. Why don't you be a bit more diligent? After all, you're a member of Daark Seven!"
L14_1.m_Talk_TWN = "亞伯特說得對。身為Dark 7的一員，能不能有點自覺，賽博貓？"
L14_1.m_Talk_THA = "จริงของอัลเบิร์ต ทำไมเธอไม่หัดกระตือรือร้นกว่านี้สักหน่อย? เพราะยังไงเธอก็เป็นสมาชิกของดาร์คเซเว่นนะ!"
L14_1.m_Talk_VTN = "Albert đúng đấy. Sao không chăm chỉ hơn nhỉ? Dù sao thì cô cũng là thành viên của Daark Seven đấy!"
L14_1.m_Talk_SCN = "艾伯特说得对。身为D7的一员，能不能有点觉悟，赛博猫？"
L14_1.m_Talk_DEU = "Albert hat recht. Warum bist du nicht ein bisschen fleißiger, Cyber Cat? Schließlich bist du doch ein Mitglied von Daark Seven!"
L14_1.m_Talk_FRA = "Albert a raison. Tu devrais faire ton travail un peu plus consciencieusement, Cyber Cat."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 31611
L15_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L15_1.m_Talk_KOREA = "……아하, 그러셔?"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "……へえ、そうくるんだ？"
L15_1.m_Talk_ENG = "...Hah. Really?"
L15_1.m_Talk_TWN = "……哀，是嗎？"
L15_1.m_Talk_THA = "...ฮะ. นี่เที่ยงแล้วหรอ ?"
L15_1.m_Talk_VTN = "...Ha. Thật đấy à?"
L15_1.m_Talk_SCN = "……啊哈，是么？"
L15_1.m_Talk_DEU = "... Aha. Wirklich?"
L15_1.m_Talk_FRA = "Hah... Vraiment ?"
L16_1 = {}
L16_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 31611
L16_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L16_1.m_Talk_KOREA = "그래. 어디 얼마나 중대한 일로 호출하셨는지 들어볼까?"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "いいわ。そんなに言うなら、どれだけ重大な仕事で呼び出したのか、聞いてみようじゃないの。"
L16_1.m_Talk_ENG = "OK. So what crucial matter is this about?"
L16_1.m_Talk_TWN = "好吧，那就讓我來聽聽，你們到底有什麼情報？"
L16_1.m_Talk_THA = "ฉันตื่นแล้ว ว่าแต่มีเรื่องสำคัญอะไรหล่ะ?"
L16_1.m_Talk_VTN = "Rồi. Vậy vào vấn đề chính đi?"
L16_1.m_Talk_SCN = "好吧。那就让我来听听，你们到底有什么情报？"
L16_1.m_Talk_DEU = "Okay. Worum geht es denn?"
L16_1.m_Talk_FRA = "Bon, d'accord. Mais qu'est-ce que ça a de si important pour qu'on m'appelle ?"
L17_1 = {}
L17_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 31611
L17_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L17_1.m_Talk_KOREA = "반드시 중요한 일이어야만 할 거야."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "重大なことじゃなかったら、わかってるわよね？"
L17_1.m_Talk_ENG = "It better be something important."
L17_1.m_Talk_TWN = "最好是有什麼重要的事。"
L17_1.m_Talk_THA = "ฉันหวังว่ามันจะเป็นเรื่องสำคัญนะ  "
L17_1.m_Talk_VTN = "Tốt hơn là nó phải quan trọng đấy."
L17_1.m_Talk_SCN = "最好是有什么重要的事。"
L17_1.m_Talk_DEU = "Es muss ja etwas äußerst Wichtiges sein."
L17_1.m_Talk_FRA = "J'espère que c'est une affaire de la plus haute importance !"
L18_1 = {}
L18_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@18#Talk"
L18_1.m_CutScenProcessKey = 18
