L18_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L18_1.m_Talk_KOREA = "그렇지 않으면 착불로 궤도 미사일을 받아보게 될 테니까."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "着払いで軌道ミサイルを送りつけてやるから。"
L18_1.m_Talk_ENG = "Or else, you'll be getting a very special package called a ballistic missile."
L18_1.m_Talk_TWN = "否則我會用貨到付款的方式，讓你們收到軌道導彈！"
L18_1.m_Talk_THA = "ไม่งั้น พวกคุณจะโดนส่งพัสดุพิเศษที่ใส่เชื้อโควิดให้นะ ในฐานะที่รบกวนเวลานอนฉัน"
L18_1.m_Talk_VTN = "Nếu không, các cậu sẽ nhận được một gói rất đặc biệt gọi là tên lửa đạn đạo."
L18_1.m_Talk_SCN = "否则，我就给你们寄轨道导弹，“到付”的那种！"
L18_1.m_Talk_DEU = "Andernfalls „schicke“ ich euch eine Orbitalrakete."
L18_1.m_Talk_FRA = "Sinon, je peux vous assurer que vous allez recevoir une livraison de missile balistique en pleine poire."
