L21_1 = {}
L21_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 31611
L21_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L21_1.m_Talk_KOREA = "이 몸께서는 이번에 개최될 관리국 테크 컨퍼런스에 대한 미공개 홍보영상을 빼돌렸단 말씀!"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "この私が、今度開催される管理局のテックカンファレンスについての未公開宣伝映像を盗み取ってきたのよ！"
L21_1.m_Talk_ENG = "Because I got leaks of the unreleased promotional video for the Administration Tech Conference that's happening soon!"
L21_1.m_Talk_TWN = "最近不是要舉辦管理局技術大會嗎？我把他們還沒公開的宣傳影片給弄來囉！"
L21_1.m_Talk_THA = "เพราะผมได้รับวิดีโอโปรโมตที่ยังไม่ประกาศเป็นทางการของการสัมมนา เทคโนโลยีองค์การบริหารโลก ที่กำลังจะจัดขึ้นเร็วๆนี้!"
L21_1.m_Talk_VTN = "Bởi vì tôi đã lấy được video quảng cáo chưa phát hành bị rò rỉ cho Hội Thảo Công Nghệ Cục Quản Lý sắp diễn ra!"
L21_1.m_Talk_SCN = "最近不是举办管理局科技大会吗，我这次把他们还未公开的宣传视频给偷来了！"
L21_1.m_Talk_DEU = "Mir ist rein zufällig das unveröffentlichte Werbevideo für die bald stattfindende Tech-Konferenz der Administration in die Hände gefallen!"
L21_1.m_Talk_FRA = "Parce que j'ai réussi à me procurer la vidéo promotionnelle inédite de la conférence sur la technologie de l'Administration qui aura bientôt lieu et qui a fuité !"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 31611
L22_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L22_1.m_Talk_KOREA = "테크 컨퍼런스? 매년 관리국 기술을 시연하는 박람회를 말하는 거지?"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "テックカンファレンス？　毎年管理局の技術を披露する博覧会のことよね？"
L22_1.m_Talk_ENG = "Tech Conference? The annual expo where they showcase the Administration's technology?"
L22_1.m_Talk_TWN = "技術大會？你說的是每年展示管理局技術的博覽會吧？"
L22_1.m_Talk_THA = "การสัมมนาด้านเทคโนโลยีหรอ? งานแสดงประจำปีที่พวกเขามานำเสนอเทคโนโลยีองค์การบริหารโลก?"
L22_1.m_Talk_VTN = "Hội Thảo Công Nghệ? Triển lãm hàng năm mà họ trưng bày công nghệ của Cục Quản Lý?"
L22_1.m_Talk_SCN = "科技大会？你说的是每年展示管理局技术的博览会吧？"
L22_1.m_Talk_DEU = "Tech-Konferenz? Das ist doch die jährliche Ausstellung, auf der die Technologie der Administration präsentiert wird, nicht wahr?"
L22_1.m_Talk_FRA = "La conférence sur la technologie ? Tu parles de l'exposition annuelle où on présente la technologie de l'Administration ?"
L23_1 = {}
L23_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 31611
L23_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L23_1.m_Talk_KOREA = "정식 라이센스가 없으면 입장할 수도 없는 행사잖아!?"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "正式ライセンスがないと入場すらできないイベントじゃないか！？"
L23_1.m_Talk_ENG = "You can't even get in without an official license!"
L23_1.m_Talk_TWN = "你說那個沒有通行證根本進不去的博覽會嗎？！"
L23_1.m_Talk_THA = "คุณเข้าไปไม่ได้หากไม่มีใบอนุญาตอย่างเป็นทางการนั่น!"
L23_1.m_Talk_VTN = "Còn không thể vào được nếu không có giấy phép chính thức!"
L23_1.m_Talk_SCN = "如果没有正式许可，根本就进不去的那个博览会啊？！"
L23_1.m_Talk_DEU = "Da kommt man doch eigentlich nur rein, wenn man eine offizielle Lizenz hat, oder?!"
L23_1.m_Talk_FRA = "On ne peut même pas y entrer sans licence officielle !"
L24_1 = {}
L24_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 31611
L24_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L24_1.m_Talk_KOREA = "엣헴! 좀 더 찬양해도 좋다고, 제군들?"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "えっへん！　もっと褒めてくれてもいいのよ、諸君？"
L24_1.m_Talk_ENG = "Ahem! Feel free to continue with the compliments."
L24_1.m_Talk_TWN = "嘿嘿！快誇我！"
L24_1.m_Talk_THA = "เอิ่ม! ผมรู้สึกอยากอธิบายต่อหากได้คำชมมากกว่า  "
L24_1.m_Talk_VTN = "E hèm! Tiếp tục khen tôi đi."
L24_1.m_Talk_SCN = "嗯哼！诸位，你们可以多赞美我几句的！"
L24_1.m_Talk_DEU = "Ähem! Ihr könnt mir gerne noch mehr Lob zusprechen."
L24_1.m_Talk_FRA = "Ahem ! Allez-y, continuez à me lancer des fleurs, mes chers !"
L25_1 = {}
L25_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 31611
L25_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L25_1.m_Talk_KOREA = "이번 테크 컨퍼런스에서는 관리국의 가상 현실 기술이 시연될 예정이야."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "今度のテックカンファレンスでは管理局のVR技術が披露される予定なの。"
L25_1.m_Talk_ENG = "This Tech Conference is going to showcase the Administration's virtual reality technology."
L25_1.m_Talk_TWN = "在這次的技術大會上，管理局會展示VR技術！"
L25_1.m_Talk_THA = "การสัมมนาด้านเทคโนโลยีครั้งนี้จะนำเสนอเทคโนโลยีเสมือนจริงขององค์การบริหารโลก"
L25_1.m_Talk_VTN = "Hội Thảo Công Nghệ này sẽ giới thiệu công nghệ thực tế ảo của Cục Quản Lý."
L25_1.m_Talk_SCN = "在这次的科技大会上，管理局会演示虚拟现实技术！"
L26_1 = "Auf dieser Tech-Konferenz soll die Virtual-Reality-Technologie der Administration vorgestellt werden."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Cette conférence sur la technologie va permettre de présenter la technologie de réalité virtuelle de l'Administration."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@26#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 26
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 31611
L26_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L27_1 = "관리국의 소개에 따르면, 장소나 환경에 구애받지 않고 어디든 구현할 수 있다고 해."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "管理局の説明によると、場所や環境に左右されず、どこにでも具現可能らしいよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "According to the Administration, it can be implemented anywhere, regardless of the location or environment."
L26_1.m_Talk_ENG = L27_1
L27_1 = "據管理局的介紹，這個技術不受場地和環境的限制，可以在任何地方使用！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ตามที่องค์การบริหารโลกกำหนดไว้ มันจะต้องสามารถเอาไปใช้ได้ทุกที่ ไม่ว่าสถานที่และสภาพแวดล้อมจะเป็นยังไง"
L26_1.m_Talk_THA = L27_1
L27_1 = "Theo Cục Quản Lý, nó có thể được thực hiện ở bất cứ đâu, bất kể vị trí hoặc môi trường."
L26_1.m_Talk_VTN = L27_1
L27_1 = "据管理局的介绍，这个技术不受场地和环境的限制，可以在任何地方使用！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Laut der Administration kann diese Technologie überall eingesetzt werden, unabhängig vom Standort oder der Umgebung."
L26_1.m_Talk_DEU = L27_1
L27_1 = "D'après eux, cette technologie peut être implémentée n'importe où, quel que soit le lieu ou l'environnement."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 31611
L27_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L28_1 = "오, 꽤 하는데? 그래서? 관리국은 그 기술로 뭘 보여줄 예정인데?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "おお、なかなかやるじゃない。で？　管理局はその技術で何を見せてくれる予定なの？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Oh, not bad. So? What is the Administration gonna do with that technology?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "噢，還不錯嘛？然後呢？管理局準備用那個技術做什麼？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "โอ้ว ดูเข้าท่าดีนะ ว่าแต่? องค์การบริหารโลกจะเอาเทคโนโลยีไปทำอะไร?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ồ, không tệ. Sao nữa? Cục Quản Lý sẽ làm gì với công nghệ đó?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "噢，还不错嘛？然后呢？管理局准备用那个技术做什么？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Oh, nicht schlecht. Aber ... Was will die Administration mit dieser Technologie zeigen?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ça vend du rêve. Et donc ? Qu'est-ce que l'Administration compte faire avec cette technologie ?"
L27_1.m_Talk_FRA = L28_1
