L30_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L31_1 = "관리국은 그 기술을 활용하여, <color=#ffd34c>유령의 집</color>을 기획하고 있어!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "管理局はその技術を活用して、<color=#ffd34c>お化け屋敷</color>を企画してるの！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "The Administration is going to utilize that technology... to organize a <color=#ffd34c>haunted house</color>!"
