L31_1 = "管理局準備利用那個技術，打造一個<color=#ffd34c>鬼屋</color>！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "องค์การบริหารโลกกำลังจะใช้เทคโนโลยีนั้น... เพื่อจัดการ<color=#ffd34c>บ้านผีสิง</color>!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cục Quản Lý sẽ sử dụng công nghệ đó... để tổ chức một <color=#ffd34c>ngôi nhà ma ám</color>!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "管理局准备利用那个技术，打造一个<color=#ffd34c>鬼屋</color>！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Die Administration wird diese Technologie nutzen, um ein <color=#ffd34c>Spukhaus</color> zu organisieren!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "L'Administration va utiliser cette technologie... pour mettre en place une <color=#ffd34c>Maison hantée</color> !"
