L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 31611
L33_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L34_1 = "그러니까, 관리국이 그 잘나 빠진 기술력으로 고작 유령의 집이나 만든 다는 말이지?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "つまり、管理局はそのご大層な技術力でお化け屋敷なんかを作るってことね。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "So, the Administration's gonna use their fancy technology to make a childish haunted house?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "就是說，管理局就打算用那個了不起的技術做一個鬼屋？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แล้วองค์การบริหารโลกจะใช้เทคโนโลยีที่สุดล้ำ เพื่อสร้างบ้านผีสิงแบบเด็กๆ นะเหรอ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vậy Cục Quản Lý sẽ sử dụng công nghệ ưa thích của họ để tạo ra một ngôi nhà ma ám cho trẻ con?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "就是说，管理局就打算用那个了不起的技术做一个鬼屋？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Die Administration hat also vor, diese herausragende Technologie zu nutzen, um ein lächerliches Spukhaus zu kreieren?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Donc si je comprends bien, l'Administration va utiliser cette technologie de pointe pour construire une stupide maison hantée ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 31611
L34_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L35_1 = "아하~ 그렇구나~ 그럼 이제 너희 집 주소를 불러줄래, 앨버트?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "へえ～そうなんだ～じゃ、そろそろアンタたちの住所を教えてくれる？　アルバート？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Ohh! Of course! Now, will you tell me your address, Albert?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "啊哈～這樣啊～那現在可以把你們的住址告訴我了嗎，亞伯特？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "โอ้ว! ชัดเจนแล้ว! แล้วตอนนี้คุณพร้อมจะบอกที่อยู่ของคุณให้ฉันได้ไหมอัลเบิร์ต?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ôi! Tất nhiên rồi! Bây giờ, cho tôi biết địa chỉ của cậu được không, Albert?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "啊哈~这样啊~那现在可以把你们的住址告诉我了吗，艾伯特？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Aha! Verstehe! Rück mal schnell mit deiner Adresse raus, Albert."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ohh ! Je vois ! Tu veux bien me donner ton adresse, Albert ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 31611
L35_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L36_1 = "굳이 최신 기술까지 쓰지 않아도, 미사일 한방이면 유령 나오는 집을 만들 수 있다는 걸 보여줄 테니까."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "最新技術まで使わなくとも、ミサイル一発で幽霊が出る家を作れるってところを見せてあげるから。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I'll showcase my own haunted house with just one missile. I don't need any state-of-the-art technology."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我可以讓你們見識一下，不使用最新技術，怎樣只靠一發導彈打造鬼屋。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เดี๋ยวฉันจะจัดส่งแบบบ้านผีสิงของตัวเองพร้อมด้วยมิสไซล์1ลูกไปให้ เพราะฉันไม่ต้องการเทคโนโลยีล้ำสมัยใดๆ "
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi sẽ giới thiệu ngôi nhà ma ám ám của riêng tôi chỉ bằng quả tên lửa. Tôi không cần bất kỳ công nghệ tiên tiến nào luôn."
L35_1.m_Talk_VTN = L36_1
L36_1 = "我可以让你们见识一下，不使用最新技术，怎样只靠一发导弹打造鬼屋。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich werde dir zeigen, wie man sein ganz eigenes Spukhaus mit nur einer einzigen Rakete erschaffen kann, ohne irgendwelche hochmoderne Technologie einzusetzen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Je peux réaliser ma propre maison hantée avec un seul missile. Pas besoin de technologie de pointe."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 31611
L36_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L37_1 = "후후후, 역시 쉽게 믿지 못하는군 사이버 캣."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ふふふ、やっぱりそう簡単に信じられないよね、サイバーキャット。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Ha ha ha, I see you don't believe me, Cyber Cat."
L36_1.m_Talk_ENG = L37_1
L37_1 = "哼哼哼，你果然不會輕易相信，賽博貓。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฮ่า ฮ่า ผมรู้ว่ายังไงคุณก็ไม่เชื่อผมหรอก แมวไซเบอร์ "
L36_1.m_Talk_THA = L37_1
L37_1 = "Ha ha ha, tôi thấy cậu không tin tôi, Cyber Cat."
L36_1.m_Talk_VTN = L37_1
L37_1 = "哼哼哼，你果然不会轻易相信啊，赛博猫。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Hahaha. Du glaubst, dass ich dich auf den Arm nehme, nicht wahr?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Ha ha ha, je vois que tu ne me crois pas, Cyber Cat."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 31611
L37_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L38_1 = "하긴, 나도 처음에는 내 눈을 의심했으니까."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "まあ、私も最初は自分の目を疑ったから。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I can't blame you. I, too, couldn't believe what I was seeing."
L37_1.m_Talk_ENG = L38_1
L38_1 = "剛開始的時候，我也以為是我自己看錯了。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ผมจะว่าคุณก็ไม่ได้ เพราะผมเองก็ไม่เชื่อในสิ่งที่เห็นและได้ฟังนี้เหมือนกัน "
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi không thể đổ lỗi cho cậu. Tôi cũng không thể tin được những gì mình đang nhìn thấy."
L37_1.m_Talk_VTN = L38_1
L38_1 = "刚开始的时候，我也以为是我自己看错了。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Aber ich kann deine Zweifel durchaus nachvollziehen. Als ich es zum ersten Mal mit meinen eigenen Augen sah, konnte ich es ebenfalls kaum glauben."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Je ne t'en veux pas. Moi non plus, je n'en croyais pas mes yeux."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 31611
L38_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L39_1 = "하지만 이 영상을 보고도 그런 말을 할 수 있을까?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "でも、この映像を見てもそんなことを言えるかな？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But will you feel the same way even after watching this video?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "但是你看了這個影片之後就不會那麼說了。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่คุณคงจะรู้สึกแบบเดียวกันกับผมถ้าได้ดูวิดีโอนี้หรือปล่าว?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng liệu cậu còn cảm thấy như vậy ngay cả sau khi xem video này không?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "但是，你看了这个视频之后就不会那么说了。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber wirst du auch nach dem Ansehen dieses Videos noch genauso denken?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais penseras-tu la même chose même après avoir regardé cette vidéo ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
