L41_1 = "m_bCharHologramEffect"
L40_1[L41_1] = true
L41_1 = "……오, 오싹오싹 고스트 하우스에 오신 걸 환영합니다, 카운터 여러분."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "……ぞ、ゾクゾク・ゴーストハウスへようこそ、カウンターの皆さん。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "...W-welcome to the Creepy Ghost House, Counters."
L40_1.m_Talk_ENG = L41_1
L41_1 = "……各，各位制裁者，歡迎來到毛骨悚然鬼屋。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "...ยินดีต้อนรับสู่บ้านผีสิงเคาน์เตอร์ที่น่าขนลุก  "
L40_1.m_Talk_THA = L41_1
L41_1 = "...Ch-chào mừng đến với Ngôi Nhà Ma Ám Rùng Rợn, Counter."
L40_1.m_Talk_VTN = L41_1
L41_1 = "……各、各位制裁者，欢迎来到毛骨悚然鬼屋。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "...W-willkommen im gruseligen Geisterhaus, Counter."
L40_1.m_Talk_DEU = L41_1
L41_1 = "B-Bienvenue dans la Maison hantée de la peur, chers Counters...!"
L40_1.m_Talk_FRA = L41_1
