L45_1 = "m_bCharHologramEffect"
L44_1[L45_1] = true
L45_1 = "……대원들의 훈련 경과는 순조롭습니다, 대령님."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "……隊員たちの訓練経過は順調です、大佐。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "...The troops' training is going smoothly, Colonel."
L44_1.m_Talk_ENG = L45_1
L45_1 = "……隊員們的訓練過程非常順利，上校。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "...การฝึกทหารดำเนินไปอย่างราบรื่นครับ ผู้พัน"
L44_1.m_Talk_THA = L45_1
L45_1 = "...Việc huấn luyện quân đội đang diễn ra suôn sẻ, thưa Đại tá."
L44_1.m_Talk_VTN = L45_1
L45_1 = "……是，队员们的训练过程非常顺利，上校大人。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "... Das Training der Truppen verläuft reibungslos, Oberst."
