L51_1 = "하아……! 하아……! 나 좀 봐, 버터맨!! 속보야, 속보라고!!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "はあ……！　はあ……！　ちょっと、バターマン！！　速報よ、速報！！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "*Huff...!* *Huff...!* I need to talk to you, Sleazeball!! I got news, BIG NEWS!!"
