L51_1 = "哈啊……！哈啊……！小白臉，小白臉！出大事啦！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "*ฮัฟ...!* *ฮัฟ...!* ฉันต้องคุยกับคุณหน่อย Sleazeball!! ฉันได้รับข่าว ข่าวใหญ่ด้วย!!"
L50_1.m_Talk_THA = L51_1
L51_1 = "*Hù...!* *Hù...!* Tôi cần nói chuyện với anh đồ nhếch nhác!! Tôi có tin này, TIN LỚN!!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "哈啊……！哈啊……！油腻男，油腻男！出大事啦！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Haah ... Haah ... Ich muss mit dir reden, Drecksack!! Ich habe Neuigkeiten, brandaktuelle Neuigkeiten!!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Haah...! Haah...! Hé, Vicelard ! J'ai un scoop ! Un gros scoop !"
