L3_1 = "응, 무슨 일이야, 실비아? 오늘 휴가였던 걸로 알고 있는데?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "うん？　どうしたんだ、シルビア。今日は休みじゃなかったのか？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Okay. What's going on, Sylvia? I thought you were on vacation today."
L2_1.m_Talk_ENG = L3_1
L3_1 = "嗯，怎麼了，希爾維亞？你今天不是休假嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ว่าไง เกิดอะไรขึ้นซิลเวีย? ผมคิดว่าวันนี้คุณจะหยุดพักผ่อนซะอีก"
