L2_1.m_Talk_VTN = L3_1
L3_1 = "嗯，怎么了，希尔薇娅？你今天不是休假吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Okay. Was ist los, Sylvia? Ich dachte, du hättest heute Urlaub."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Quoi ? Qu'est-ce qui se passe, Sylvia ? Je croyais que tu étais de repos aujourd'hui."
