L8_1 = "실비아 씨. 지금은 업무 보고 중인 거 안 보입니까?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "シルビアさん。今は業務報告中ですが。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Sylvia. Can't you see that I am in the middle of reporting something?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "希爾維亞，你沒看見我正在彙報工作嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ซิลเวีย คุณไม่เห็นหรอว่าผมกำลังทำรายงานบางอย่างอยู่?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Sylvia. Cô không thấy tôi đang bận báo cáo sao?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "希尔薇娅，你没看见我正在汇报工作吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Sylvia. Siehst du denn nicht, dass ich gerade dabei bin, etwas zu melden?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Sylvia. Ne voyez-vous pas que nous sommes en plein rapport de travail ?"
L7_1.m_Talk_FRA = L8_1
