L9_1 = "m_bCharHologramEffect"
L8_1[L9_1] = true
L9_1 = "뭔지는 몰라도 영양가 없는 잡담은 나중에 하십쇼."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "何だか知りませんが、無意味な雑談は後にしてください。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Whatever your trivial gossip may be, you can wait until the reports are finished."
L8_1.m_Talk_ENG = L9_1
L9_1 = "雖然我不知道你有什麼事，但沒有意義的閒話還是等會兒再說吧。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ไม่ว่าเรื่องซุบซิบนินทา ของคุณคืออะไร คุณรอจนกว่าผมจะทำรายงานเสร็จทั้งหมดก่อน"
L8_1.m_Talk_THA = L9_1
L9_1 = "Dù tin đồn tầm thường của cô là gì, cô có thể đợi cho đến khi báo cáo xong."
L8_1.m_Talk_VTN = L9_1
L9_1 = "虽然我不知道你有什么事，但没有意义的闲话还是等会儿再说吧。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich weiß zwar nicht, worum es geht, aber heb dir das Geschwätz für später auf."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Quels que soit vos petits potins, ils peuvent attendre la fin de notre discussion."
L8_1.m_Talk_FRA = L9_1
