L12_1 = "뭡니까, 왜 그렇게 당황하죠? 저한테 뭐 숨기는 거라도 있습니까?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "何ですか、どうしてそんなに慌ててるんですか？　僕に何か隠し事でも？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "What is it? Why are you flustered? Are you hiding something from me?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "怎麼回事，幹嘛那麼驚慌？難道你有什麼事瞞著我？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เป็นอะไรไป? ทำไมคุณถึงตื่นตูมขนาดนั้น? คุณมีอะไรปิดบังผมอยู่หรือเปล่า?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Sao thế? Tại sao cô lại bối rối? Cô đang giấu tôi cái gì phải không?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "怎么回事，干吗那么惊慌？难道你有什么事瞒着我？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Was ist los? Warum bist du nervös? Verheimlichst du etwas?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Que vous arrive-t-il ? Vous me semblez fort agitée. Me cacheriez-vous quelque chose ?"
L11_1.m_Talk_FRA = L12_1
