L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "と、とにかく！　カイルとの話が終わったら、ちょっとアタシのところに来て、バターマン！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "A-anyway! We gotta talk after you're done with Kyle, Sleazeball!!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "總，總之！等凱爾彙報完之後我們談談吧，小白臉！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ย-ยังไงก็เถอะ! เราต้องคุยกันหลังไมค์รอคุณกับไคล์เสร็จธุระก่อน Sleazeball!!"
L17_1.m_Talk_THA = L18_1
L18_1 = "D-dù sao đi nữa! Chúng ta phải nói chuyện sau khi anh xong việc với Kyle, đồ nhếch nhác!!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "总、总之！等凯尔汇报完之后我们谈谈吧，油腻男！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "E-egal! Lass uns reden, nachdem du mit Kyle fertig bist, Drecksack!!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "E-Enfin bref ! Viens me voir quand tu auras fini de discuter avec Kyle, Vicelard !"
