L24_1.m_CharStrID = L25_1
L25_1 = "L"
L24_1.m_Pos = L25_1
L25_1 = "m_Crash"
L24_1[L25_1] = 20
L25_1 = "하하, 설마 이런 식으로 데이트 신청을 받을 줄은 몰랐는걸?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "はは、まさかこんな風にデートに誘われるなんてな。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Ha ha, I never thought anyone would ask me out to a haunted house."
L24_1.m_Talk_ENG = L25_1
L25_1 = "哈哈，沒想到你會以這種方式約我出去？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฮ่าๆ ไม่คิดว่าจะมีใครมาชวนไปบ้านผีสิงแบบนี้"
L24_1.m_Talk_THA = L25_1
L25_1 = "Ha ha, tôi chưa bao giờ nghĩ sẽ có người rủ mình đi chơi nhà ma."
L24_1.m_Talk_VTN = L25_1
L25_1 = "哈哈，没想到你会以这种方式邀我约会啊？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Haha, ich hätte nie gedacht, dass mich mal jemand auf ein Date in ein Spukhaus einladen würde."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Ha ha, je n'aurais jamais imaginé qu'on me proposerait ce genre de rendez-vous un jour."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 31611
L25_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "JAKE_DELTA_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "L"
L25_1.m_Pos = L26_1
L26_1 = "그런데 어쩌나, 사내연애는 별로 내 취향이 아닌데."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "でも悪いな、職場恋愛は俺の好みじゃないんだ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Unfortunately, dating coworkers is not really my thing."
L25_1.m_Talk_ENG = L26_1
L26_1 = "但怎麼辦呢，我對辦公室戀情沒興趣欸。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "น่าเสียดายที่การออกเดทกับเพื่อนร่วมงานไม่ใช่หน้าที่ของฉันจริงๆ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Thật không may, hẹn hò với đồng nghiệp không hẳn là sở thích của tôi."
L25_1.m_Talk_VTN = L26_1
L26_1 = "但怎么办才好呢，我不准备发展办公室恋情啊。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Leider ist es nicht so mein Ding, mit Kollegen auszugehen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Malheureusement, sortir avec une collègue de travail, ce n'est pas vraiment mon truc, tu sais."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 31611
L26_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "UNIT_PRIDE"
L26_1.m_Face = L27_1
L26_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L27_1 = "R"
L26_1.m_Pos = L27_1
L27_1 = "m_Crash"
L26_1[L27_1] = 20
L27_1 = "하아, 개소리 하는 걸 보니 전혀 못 알아먹었네."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "はあ、ばかなこと言ってるところを見ると、全っ然理解してないわね。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "*Sigh* You're still not getting the point."
L26_1.m_Talk_ENG = L27_1
L27_1 = "哼，看你鬼話連篇的樣子，是一點都沒聽懂我說的。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "*ถอนหายใจ* เฮ่บย คุณยังไม่เก็ทประเด็นอีก"
L26_1.m_Talk_THA = L27_1
L27_1 = "*Thở dài* Anh vẫn chưa hiểu ý tôi."
L26_1.m_Talk_VTN = L27_1
L27_1 = "哼，看你鬼话连篇的样子，是一点都没听懂我说的。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Haah ... Du redest echt kompletten Mist und verstehst kein Stück, worum es eigentlich geht."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Pff, mais non, tu ne comprends pas où je veux en venir."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 31611
L27_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L28_1 = "R"
L27_1.m_Pos = L28_1
L28_1 = "m_Crash"
L29_1 = 30
L27_1[L28_1] = L29_1
L28_1 = "하긴, 믿어주리라고는 기대도 안 했어. 나도 보기 전까진 못 믿었으니까."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "まあ、信じてくれるなんて期待してなかったけどね。アタシだって実際見るまでは信じられなかったから。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Well, I didn't expect you to believe me right away. I didn't believe it until I saw it myself."
L27_1.m_Talk_ENG = L28_1
L28_1 = "不過我也沒指望你會信，因為在看到影片之前我也是不相信的。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ฉันไม่ได้หวังให้คุณเชื่อฉันตอนนี้ ฉันเองก็ไม่เชื่อจนกระทั่งฉันได้เห็นมันด้วยตัวเอง"
L27_1.m_Talk_THA = L28_1
L28_1 = "Chà, tôi không mong đợi anh sẽ tin tôi ngay lập tức. Tôi đã không tin cho đến khi chính mắt tôi nhìn thấy nó."
L27_1.m_Talk_VTN = L28_1
L28_1 = "不过我也没指望你会信，因为在看到视频之前我也是不相信的。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Nun, ich hatte auch nicht erwartet, dass du mir sofort glauben würdest. Ich habe es auch nicht glauben können, bis ich es mit eigenen Augen gesehen habe."
L27_1.m_Talk_DEU = L28_1
L28_1 = "À vrai dire, j'imaginais bien que tu ne me croirais pas. Même moi je n'y croyais pas avant de l'avoir vu de mes propres yeux."
L27_1.m_Talk_FRA = L28_1
