L30_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 31611
L29_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "UNIT_SURPRISE"
L29_1.m_Face = L30_1
L30_1 = "JAKE_DELTA_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "m_Crash"
L29_1[L30_1] = 20
L30_1 = "대체 뭔데 그렇게 호들갑이야? 설마 유령이 무서워서 그러는 건 아닐 테고."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "大げさに、いったい何なんだ？　まさか、幽霊が怖いってわけでもないだろうし。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "What's all the fuss about? You're not afraid of ghosts, are you?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "到底是什麼東西讓你這麼大驚小怪的？你不會是怕鬼吧？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เอ ว่าแต่ ทั้งหมดมันเกี่ยวกับอะไร? แล้วคุณไม่กลัวผีใหรอ?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tóm lại là cái gì mà sốt sắng vậy? Cô không sợ ma chứ?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "到底是什么东西让你这么大惊小怪的？你总不会是怕鬼吧。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Was soll denn die ganze Aufregung? Du hast doch keine Angst vor Geistern, oder?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Pourquoi tu t'excites pour si peu ? Ne me dis pas que tu as peur des fantômes, quand même ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 31611
L30_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
