L30_1.m_fWaitTime = 0
L31_1 = "UNIT_LAUGH"
L30_1.m_Face = L31_1
L30_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "아니, 어떤 의미에서 유령보다 더 무섭고 끔찍할지도 몰라."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "いや、ある意味、幽霊より怖くてぞっとするかもしれないわよ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Nope, but in some ways, this might be more terrifying than ghosts."
L30_1.m_Talk_ENG = L31_1
L31_1 = "不，從某種意義上來說，那也許比鬼更可怕。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ไม่เลย แต่บางทีนี่มันอาจจะน่ากลัวกว่าผีก็ได้"
L30_1.m_Talk_THA = L31_1
L31_1 = "Không, nhưng ở một khía cạnh nào đó, điều này có thể còn đáng sợ hơn cả ma."
L30_1.m_Talk_VTN = L31_1
L31_1 = "不，从某种意义上说，那也许比鬼更可怕。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Nein, aber in gewisser Hinsicht könnte es noch furchterregender sein als irgendwelche Geister."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Pas du tout. Mais d'une certaine façon, c'est peut-être encore plus terrifiant que des fantômes..."
L30_1.m_Talk_FRA = L31_1
