L32_1.m_Face = L33_1
L32_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "영상을 틀기 전에 하나만 물을게, 버터맨."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "バターマン、映像を再生する前に一つだけ聞くけど。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Before I play the video, I have one question, Sleazeball."
L32_1.m_Talk_ENG = L33_1
L33_1 = "在放影片之前，我要問你一個問題，小白臉。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ก่อนที่ฉันจะกดดูวิดีโอ ฉันมีคำถามหนึ่งข้อ Sleazeball"
L32_1.m_Talk_THA = L33_1
L33_1 = "Trước khi phát video, tôi có một câu hỏi, đồ nhếch nhác."
L32_1.m_Talk_VTN = L33_1
L33_1 = "在放视频之前，我要问你一个问题，油腻男。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Bevor ich das Video abspiele, möchte ich dir eine Frage stellen, Drecksack."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Avant de lancer la vidéo, j'ai une question à te poser, Vicelard."
L32_1.m_Talk_FRA = L33_1
