L34_1 = "m_Crash"
L33_1[L34_1] = 20
L34_1 = "카일의 인적 사항에 누나나 여동생은 없었지?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "カイルにお姉さんとか妹はいなかったわよね？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Do you know if Kyle has a sister or something?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "凱爾的個人資料裡並沒有寫他有姊姊或妹妹吧？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "คุณรู้ไหมว่าไคล์มีน้องสาวหรือญาติไหม?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Anh có biết liệu Kyle có em gái hay gì không?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "凯尔的个人资料里并没有写他有姐姐或者妹妹吧？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "In Kyles persönlicher Akte war nicht vermerkt, dass er eine Schwester hat, oder?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Tu sais si Kyle a une sœur ?"
