L37_1.m_Talk_JPN = L38_1
L38_1 = "...W-welcome to the Creepy Ghost House, Counters."
L37_1.m_Talk_ENG = L38_1
L38_1 = "……各，各位制裁者，歡迎來到毛骨悚然鬼屋。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "...ยินดีต้อนรับสู่บ้านผีสิงเคาน์เตอร์น่าขนลุก  "
L37_1.m_Talk_THA = L38_1
L38_1 = "...Ch-chào mừng đến với Ngôi Nhà Ma Ám Rùng Rợn, Counter."
L37_1.m_Talk_VTN = L38_1
L38_1 = "……各、各位制裁者，欢迎来到毛骨悚然鬼屋。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "... W-willkommen im gruseligen Geisterhaus, Counter."
L37_1.m_Talk_DEU = L38_1
L38_1 = "B-Bienvenue dans la Maison hantée de la peur, chers Counters...!"
L37_1.m_Talk_FRA = L38_1
