L2_1[L3_1] = 20
L3_1 = "……처음에는 당연히 합성된 가짜 동영상이라고 생각했는데, 감별 프로그램을 돌려보니 그건 아니었어."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "……最初は当然捏造された映像だと思ったんだけど、鑑別プログラムにかけてみたらそうじゃなかった。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "...At first, I thought it was fake, that it was deepfaked or something. But I ran a forensics program and it didn't catch anything."
L2_1.m_Talk_ENG = L3_1
L3_1 = "……一開始我還以為這是合成的假影片，但經過鑒定之後才發現是真的。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "...ตอนแรกนึกว่าของปลอม นึกว่าเป็นการตัดต่อ หรืออะไรสักอย่าง แต่ฉันทำโปรแกรมตรวจสอบระบบ   ก็เชคหาไม่เจอการตัดต่อ"
L2_1.m_Talk_THA = L3_1
L3_1 = "...Lúc đầu, tôi nghĩ nó là giả, deepfake hay gì đó. Nhưng tôi đã chạy một chương trình pháp y nhưng không thu được gì cả."
L2_1.m_Talk_VTN = L3_1
L3_1 = "……一开始我还以为这是合成的假视频，但经过鉴定之后才发现是真的。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "... Zuerst dachte ich, es handle sich um ein gefälschtes, bearbeitetes Video, aber als ich es mit einem Programm überprüft habe, stellte sich heraus, dass das Video echt ist."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Au début, je pensais que c'était un montage, un Deepfake ou quelque chose dans le genre... Mais je l'ai faite vérifier par un programme de détection de vidéos truquées, et ce n'est pas le cas."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@103#Talk"
