L3_1.m_Pos = "C"
L4_1 = "그렇다면 가능성은 두 가지 중 하나."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "だとすると、可能性は二つ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Which means there are only two options left."
