L4_1.m_fTalkTime = 0.03
L5_1 = "カイルに似てる女か……"
L4_1.m_Talk_JPN = L5_1
L5_1 = "It's a woman who looks like Kyle..."
L4_1.m_Talk_ENG = L5_1
L5_1 = "一是有個長得很像凱爾的女人……"
L4_1.m_Talk_TWN = L5_1
L5_1 = "มีผู้หญิงที่หน้าตาเหมือนไคล์..."
L4_1.m_Talk_THA = L5_1
