L6_1 = "진짜 여장한 카일이거나!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "本当に女装したカイルか！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Or it's Kyle dressed up as a woman!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "二是凱爾男扮女裝！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "หรือจะเป็นไคล์ที่แต่งตัวเป็นผู้หญิง!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Hoặc đó là Kyle mặc đồ như phụ nữ!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "要么就是——男扮女装的真凯尔！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Kyle hat sich als Frau verkleidet!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Soit c'est Kyle déguisé en femme !"
