L9_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 31611
L8_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "UNIT_DESPAIR"
L8_1.m_Face = L9_1
L9_1 = "JAKE_DELTA_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "L"
L8_1.m_Pos = L9_1
L9_1 = "에이, 실비아. 아무리 그래도 카일을 대체 뭐라고 생각하는 거야?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "おい、シルビア。カイルのこと何だと思ってるんだ？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "C'mon, Sylvia. Who do you think Kyle is?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "哎呀，希爾維亞，再怎麼說，你也不能把凱爾想得那麼不堪吧？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เอาล่ะ ซิลเวีย คุณคิดว่าใคล์คือใคร?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Thôi nào, Sylvia. Cô nghĩ Kyle là ai?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "哎呀，希尔薇娅。再怎么说，你也不能把凯尔想得那么不堪吧？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ach, Sylvia. Wie kommst du denn darauf, dass Kyle so etwas tun würde?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Sérieusement, Sylvia. Pour qui tu le prends, Kyle ?"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 31611
L9_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "UNIT_IDLE"
L9_1.m_Face = L10_1
L10_1 = "JAKE_DELTA_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "L"
L9_1.m_Pos = L10_1
L10_1 = "m_Crash"
L9_1[L10_1] = 10
L10_1 = "상식적으로 그냥 닮은 사람이겠지. 세상에는 자길 닮은 사람이 세 명은 있다고 하잖아?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "常識的に考えて単なる他人の空似だろ。世の中には自分に似たやつが三人はいるっていうじゃないか。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "It's probably just someone who looks like him. They say you have at least three doppelgangers out there in the world."
L9_1.m_Talk_ENG = L10_1
L10_1 = "按常理來說，就是長得像而已。不是說在這個世界上，起碼會有三個跟自己長得很像的人嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "คงเป็นแค่คนที่หน้าเหมือนเขาก็แค่เท่านั้น พวกเขายังบอกว่าคุณเองก็มีร่างโคลนอย่างน้อยตั้งสามคนในโลกนี้"
L9_1.m_Talk_THA = L10_1
L10_1 = "Có lẽ đó chỉ là một người trông giống cậu ấy. Họ nói rằng có ít nhất ba song trùng trên thế giới."
L9_1.m_Talk_VTN = L10_1
L10_1 = "按常理来说，就是长得像而已。不是说在这个世界上，起码会有三个自己的克隆吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Es ist wahrscheinlich nur jemand, der ihm verdammt sieht. Man sagt doch, dass es von jedem Menschen mindestens drei Doppelgänger auf der Welt gibt."
L9_1.m_Talk_DEU = L10_1
L10_1 = "C'est probablement juste quelqu'un qui lui ressemble. Il parait qu'on a tous moins trois doppelgangers dans le monde."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 31611
L10_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "JAKE_DELTA_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "L"
L10_1.m_Pos = L11_1
L11_1 = "그러고보니…… 예전에 카일을 닮은 여자가 연구 기지를 습격했다는 보고가 있었던 것 같기도 하고……."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "そういえば……前にカイルに似た女が研究基地を襲撃したという報告があったような……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "But then again... I vaguely remember a report about a woman who looks like Kyle ambushing our research facilities…"
L10_1.m_Talk_ENG = L11_1
L11_1 = "這麼說來……我好像看過一則報導，說是有一個酷似凱爾的女人襲擊研究基地……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แต่อีกอย่าง... ผมจำรายงานคร่าวๆเกี่ยวกับผู้หญิงหน้าเหมือนไคล์ ที่เคยซุ่มโจมตีศูนย์วิจัยของเราได้"
L10_1.m_Talk_THA = L11_1
L11_1 = "Nhưng một lần nữa... Tôi mơ hồ nhớ đến một báo cáo người phụ nữ trông giống Kyle đang phục kích cơ sở nghiên cứu của chúng ta."
L10_1.m_Talk_VTN = L11_1
L11_1 = "话说……以前好像有人上报过，说是有一个酷似凯尔的女人袭击了研究基地……"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Jetzt, wo ich so darüber nachdenke ... Ich erinnere mich vage an einen Bericht über eine Frau, die früher mal unsere Forschungseinrichtungen überfallen und Kyle sehr ähnlich gesehen hat ..."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Mais c'est vrai que... Je me souviens vaguement d'un rapport à propos d'une femme ressemblant à Kyle qui avait lancé un assaut sur notre centre de recherche…"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
