L12_1 = "m_Crash"
L11_1[L12_1] = 20
L12_1 = "사람 일 모르는 거야, 버터맨."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "人なんてわかんないものよ、バターマン。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "You never know, Sleazeball."
L11_1.m_Talk_ENG = L12_1
L12_1 = "人心難測，小白臉。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "คุณไม่รู้อะไรเลยจริงๆ  Sleazeball "
L11_1.m_Talk_THA = L12_1
L12_1 = "Anh không bao giờ biết được, đồ nhếch nhác."
L11_1.m_Talk_VTN = L12_1
L12_1 = "啧啧，人心难测啊，油腻男。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Man weiß nie, welche Geheimnisse ein Mensch verbirgt, Drecksack."
L11_1.m_Talk_DEU = L12_1
L12_1 = "On n'est jamais sûrs de rien, Vicelard !"
L11_1.m_Talk_FRA = L12_1
