L14_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 31611
L13_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L13_1.m_bWaitClick = true
