L14_1 = "UNIT_IDLE"
L13_1.m_Face = L14_1
L13_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "인터넷만 봐도, 말도 안 되는 취향을 가진 사람들이 얼마나 많은데."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ネットでも、あり得ないフェチを持ってる人がごまんといるんだから。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Just look at the internet. There are countless people with absurd tastes."
L13_1.m_Talk_ENG = L14_1
L14_1 = "光是在網路上，就能看到很多興趣古怪的人。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "หัดเข้าอินเทอร์เน็ตบ้าง ในโลกนี้ยังมีผู้คนนับไม่ถ้วนที่มีรสนิยมที่ไร้สาระอยู่"
L13_1.m_Talk_THA = L14_1
L14_1 = "Chỉ cần nhìn vào internet. Có vô số người có sở thích ngớ ngẩn."
L13_1.m_Talk_VTN = L14_1
L14_1 = "光是网络上，就能看到很多取向荒唐的人。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Schau dir bloß mal das Internet an. Es gibt unzählige Menschen mit absurden Geschmäckern."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Rien que sur internet, on trouve tout un tas de gens avec des goûts complètement délirants."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 31611
L14_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L14_1.m_Pos = "C"
L15_1 = "혹시, 그 애늙은이가 우리 앞에서는 샌님인 척하고…… 뒤에서는 음습한 취미를 가지고 있다고 해도 그리 이상한 일이 아니야."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "あのませガキだって、アタシたちの前ではいい子のふりながら……裏で陰険な趣味を持っていたとしても、そうおかしくはないわ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "That old soul acts all uptight in front of us... but it's possible that he dabbles in shady hobbies behind our backs."
L14_1.m_Talk_ENG = L15_1
L15_1 = "那個小老頭就算在我們面前裝成一副嚴肅的樣子……但背地裡卻有著不可告人的嗜好也不是什麼稀奇的事。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "วิญญาณแก่นั่นทำท่าขู่ต่อหน้าเรา... แต่ก็เป็นไปได้ที่เขาจะงมงายอยู่กับงานอดิเรกลับๆ ลับๆ ของเราด้วย"
L14_1.m_Talk_THA = L15_1
L15_1 = "Linh hồn già nua đó tỏ ra cứng rắn trước mặt... nhưng biết đâu cậu ta lại có sở thích mờ ám sau lưng chúng ta."
L14_1.m_Talk_VTN = L15_1
L15_1 = "那个小老头即使在我们面前装成一副严肃的样子……但背地里却有着阴暗的嗜好也不是什么稀奇的事。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Diese alte Seele benimmt sich in unserem Beisein ganz brav und anständig ... aber es ist möglich, dass er hinter unserem Rücken zwielichtigen Hobbys nachgeht."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ce vieux croûton agit de manière distinguée devant nous... mais il est tout à fait possible qu'il se livre à des passe-temps louches sans qu'on le sache."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
