L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 31611
L34_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "UNIT_IDLE"
L34_1.m_Face = L35_1
L35_1 = "JAKE_DELTA_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "L"
L34_1.m_Pos = L35_1
L35_1 = "꽤 그럴 싸한데, 이 기술을 훈련에 도입하면 상당히 도움이 되겠어."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "かなり現実に近いな。この技術を訓練に導入すれば大いに役立ちそうだ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Not bad. It would be of great help if we implemented this technology into our training."
L34_1.m_Talk_ENG = L35_1
L35_1 = "像不像三分樣，把這個技術應用到訓練中的話應該很有幫助。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ไม่เลวน้อ แต่มันจะดีมากหากเรานำเทคโนโลยีนี้ไปใช้ในการฝึกอบรมของเรา"
L34_1.m_Talk_THA = L35_1
L35_1 = "Không tệ. Sẽ rất hữu ích nếu chúng ta triển khai công nghệ này vào chương trình đào tạo của mình."
L34_1.m_Talk_VTN = L35_1
L35_1 = "还挺像样的，把这个技术应用到训练中的话应该很有帮助。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Nicht schlecht. Es wäre bestimmt eine große Hilfe, wenn wir diese Technologie in unser Training integrieren könnten."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Pas mal. Ça serait vraiment pratique si on pouvait implémenter cette technologie dans nos séances d'entraînement."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 31611
L35_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L36_1 = "R"
L35_1.m_Pos = L36_1
L36_1 = "m_Crash"
L35_1[L36_1] = 20
L36_1 = "으휴, 이 근육뇌야. 훈련 생각 같은 건 나중에 하고 지금은 빨리 빨간 망토의 정체를……."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "まったく、この脳筋バカときたら。訓練のことなんか後回しにして、今は早く赤ずきんの正体を……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Ugh, is your brain made up of muscles too? Forget about training, just focus on uncovering who that Red Riding–"
L35_1.m_Talk_ENG = L36_1
L36_1 = "嘖，你這個肌肉腦，訓練什麼的等以後再說，現在最重要的是要弄清楚紅色披風的……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เอ่อ หัวคุณคิดแต่เรื่องฉากประกอบนี้หรอคะ? ลืมเรื่องการฝึกไปก่อนไหม ให้ความสำคัญตามหาว่าใครคือหนูน้อยหมวกแดง–"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ugh, bộ não của anh cũng được làm từ cơ bắp à? Quên việc huấn luyện đi, hãy tập trung tìm xem Cô Bé Quàng Khăn Đỏ đó là ai–"
L35_1.m_Talk_VTN = L36_1
L36_1 = "哈，你的脑子里是不是全是肌肉？训练什么的等以后再想，现在最重要的是我们要弄清楚红色披风的……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Urgh, besteht dein Gehirn auch nur aus Muskeln? Vergiss mal für einen Moment das Training und konzentriere dich lieber darauf, herauszufinden, wer dieses Rotkäppchen ist –"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Pff, arrête un peu de penser avec tes muscles. Oublie l'entraînement et concentre-toi plutôt sur la découverte de qui est véritablement ce Petit Chaperon rouge..."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
