L38_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 31611
L37_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "KYLE_DELTA_APHALLOWEEN_QM"
L37_1.m_CharStrID = L38_1
L38_1 = "저, 혹시 델타 세븐의 제이크 대령님 맞으신가요?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "あの、もしかしてデルタセブンのジェイク大佐ではありませんか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Um, are you Colonel Jake Walker of Delta Seven?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "請問，你是第七三角洲部隊的傑克上校嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เอ่อ คุณคือผู้พันเจค วอล์คเกอร์ แห่งเดลต้าเซเว่นใช่ไหม?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Ừm, anh có phải Đại tá Jake Walker của Delta Seven không?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "请问，你是德尔塔部队的杰克上校吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ähm, sind Sie vielleicht Oberst Jake Walker von Delta Seven?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Excusez-moi, vous êtes bien le colonel Jake Walker de Delta Seven, n'est-ce pas ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 31611
L38_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "UNIT_LAUGH"
L38_1.m_Face = L39_1
L39_1 = "JAKE_DELTA_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "L"
L38_1.m_Pos = L39_1
L39_1 = "m_Crash"
L38_1[L39_1] = 10
L39_1 = "아, 네. 그렇습니다만. 그쪽의 레이디는 성함이……."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "あ、はい。そうですが。そちらのレディーは……？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Oh, yes. I am. And you are, my lady...?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "是的，沒錯。請問小姐貴姓……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "โอ้ใช่ครับ แล้วคุณล่ะครับคุณผู้หญิงคือ...?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ồ, vâng. Tôi đây. Còn cô là ai, thưa cô...?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "是的，没错。请问这位小姐贵姓……"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Oh, ja. Der bin ich. Und wie lautet Ihr Name, meine Dame?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Euh, oui, c'est bien moi. Et vous, mademoiselle ? Vous êtes...?"
L38_1.m_Talk_FRA = L39_1
