L42_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 31611
L41_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "UNIT_IDLE"
L41_1.m_Face = L42_1
L42_1 = "CATHY_CIVIL_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "L"
L41_1.m_Pos = L42_1
L42_1 = "아, 반갑습니다. 전 오피셜 서포트의 캐시라고 해요. 테크 컨퍼런스의 취재를 맡고 있죠."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "あ、はじめまして。私はオフィシャルサポートのキャシーと言います。テックカンファレンスの取材を担当しております。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Ah, nice to meet you. I'm Cathy, from Official Support. I'm covering the tech conference."
L41_1.m_Talk_ENG = L42_1
L42_1 = "很高興見到你，我是支援小隊的凱西，來技術大會進行採訪工作。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "อา ยินดีที่ได้รู้จักค่ะ ฉันชื่อเคธี่จากออฟฟิเชียลซัพพอร์ต ฉันกำลังสัมมนาด้านเทคโนโลยี"
L41_1.m_Talk_THA = L42_1
L42_1 = "À, rất vui được gặp anh. Tôi là Cathy, từ bộ phận Hỗ trợ Chính thức. Tôi đang đưa tin về Hội Thảo Công Nghệ."
L41_1.m_Talk_VTN = L42_1
L42_1 = "啊，很高兴见到你。我是支援小队的凯西，来科技大会进行采访工作。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ah, freut mich, Sie kennenzulernen. Ich bin Cathy von der Offiziellen Unterstützung. Ich bin für die Berichterstattung der Tech-Konferenz verantwortlich."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Ah, ravie de vous rencontrer. Je suis Cathy, d'Official Support. Je m'occupe de couvrir la conférence sur la technologie."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 31611
L42_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
