L43_1 = "UNIT_LAUGH"
L42_1.m_Face = L43_1
L43_1 = "CATHY_CIVIL_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "L"
L42_1.m_Pos = L43_1
L43_1 = "m_Crash"
L42_1[L43_1] = 10
L43_1 = "리플레이서 사태를 해결한 델타 세븐의 영웅을 이렇게 직접 보게 되서 무척 영광이네요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "リプレイサー事件を解決したデルタセブンの英雄にこうして直接お会いできるなんて、大変光栄です。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "It's an honor to meet the hero of Delta Seven who resolved the Replacer incident."
L42_1.m_Talk_ENG = L43_1
L43_1 = "沒想到我能親眼見到解決克隆集團事件的第七三角洲部隊英雄，真是倍感榮幸。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "นับเป็นเกียรติอย่างยิ่งที่ได้พบกับวีรบุรุษของเดลต้าเซเว่น ผู้แก้ไขสถานการณ์จากเหตุการณ์รีเพลสเซอร์"
L42_1.m_Talk_THA = L43_1
L43_1 = "Thật vinh dự được gặp người hùng của Delta Seven, người đã giải quyết sự cố Người Nhân Bản."
L42_1.m_Talk_VTN = L43_1
L43_1 = "没想到我能亲眼见到解决了克隆集团事件的德尔塔部队英雄，真是倍感荣幸啊。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Es ist mir eine Ehre, den Helden von Delta Seven zu treffen, der das Replacer-Fiasko bewältigt hat."
L42_1.m_Talk_DEU = L43_1
L43_1 = "C'est un honneur de rencontrer le héros de Delta Seven qui a résolu l'incident des substituts."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 31611
L43_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "CATHY_CIVIL_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "L"
L43_1.m_Pos = L44_1
L44_1 = "잠시 이야기 나누고 싶은데 혹시 시간 좀 있으신가요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "少々お話を伺いたいんですが、お時間よろしいでしょうか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I'd love to have a word with you. Do you have a moment?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "我想和你聊一聊，不知道有沒有空呢？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันอยากจะพูดคุยกับคุณ คุณมีเวลาสักครู่ไหมคะ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi rất muốn có đôi lời với anh. Anh rảnh chứ?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "我想和你聊一聊，不知道有没有空呢？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich würde mich gerne kurz mit Ihnen unterhalten. Haben Sie einen Moment Zeit?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "J'adorerais m'entretenir avec vous, auriez-vous une minute ?"
L43_1.m_Talk_FRA = L44_1
