L47_1 = "m_Crash"
L46_1[L47_1] = 10
L47_1 = "훗, 별 말씀을. 군인이 당연히 해야 할 일을 했을 뿐입니다."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ふっ、なんてことはありません。軍人として当然やるべきことをしたまでです。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Heh, no worries. I was just doing what any soldier would do."
L46_1.m_Talk_ENG = L47_1
L47_1 = "哈哈，過獎了，我只是做我該做的而已。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เฮ่ ไม่ต้องเป็นห่วง ผมก็แค่ทำในสิ่งที่ทหารคนไหนๆก็ทำกัน"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ha, không có gì. Tôi chỉ đang làm điều mà bất kỳ người lính nào cũng sẽ làm."
L46_1.m_Talk_VTN = L47_1
L47_1 = "哈哈，过奖了。我只是做了我该做的事。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Haha, vielen Dank. Ich habe einfach das getan, was jeder Soldat in dieser Situation getan hätte."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Hé hé, ce n'est rien, vous savez. J'ai simplement fait mon devoir de soldat."
L46_1.m_Talk_FRA = L47_1
