L49_1.m_CharStrID = L50_1
L50_1 = "C_F_R"
L49_1.m_Pos = L50_1
L50_1 = "……저, 저, 저, 정말로 그 제이크 워커 대령님이세요?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "……ほ、ほ、ほ、本当にあのジェイク・ウォーカー大佐ですか？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "...Um, a-a-are you THE Colonel Jake Walker?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "……你，你，你，你真的是傑克·沃克上校？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "...เอ่อ คุณคือผู้พันเจค วอล์กเกอร์ใช่ไหมค่ะ?"
L49_1.m_Talk_THA = L50_1
L50_1 = "...Ừm, aa-anh có phải là Đại tá Jake Walker không?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "……你、你、你、你真的是杰克·沃克上校大人？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "... Ähm, s-s-sind Sie wirklich DER Oberst Jake Walker?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "V-V-Vous êtes vraiment le fameux colonel Jake Walker...?"
L49_1.m_Talk_FRA = L50_1
