L52_1 = 30
L50_1[L51_1] = L52_1
L51_1 = "호, 혹시 싸인 좀 부탁드려도 될까요? 제, 제가 팬이라서요!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "も、もしかして、サインお願いしてもいいですか？　わ、私、ファンなんです！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "C-can I get your autograph? I-I'm a huge fan!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "能，能幫我簽名嗎？我，我是你的粉絲！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "แ-ฉันขอลายเซ็นของคุณได้ไหมค่ะ? ฉัน-ฉันเป็นแฟนตัวยงของคุณเลยค่ะ!"
L50_1.m_Talk_THA = L51_1
L51_1 = "T-tôi có thể xin chữ ký của anh không? Tôi là một fan của anh á!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "能、能给我签个名吗？我、我是你的忠实粉丝！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "K-könnte ich vielleicht ein Autogramm bekommen? I-ich bin ein riesiger Fan von Ihnen!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "E-Est-ce que je pourrais avoir un autographe, s'il vous plaît ? Je suis une grande fan !"
L50_1.m_Talk_FRA = L51_1
