L3_1 = "m_Crash"
L2_1[L3_1] = 20
L3_1 = "하하, 물론이죠. 시간은 얼마든지 있답니다, 아가씨."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "はは、もちろんです。時間ならいくらでもあります、お嬢さん。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Ha ha, of course. I have plenty of time, ladies."
L2_1.m_Talk_ENG = L3_1
L3_1 = "哈哈哈，當然可以，我隨時有空，美麗的小姐。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ฮ่าฮ่า ได้อยู่แล้ว ฉันยังมีเวลาอีกมากเลยนะสาวๆ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ha ha, tất nhiên rồi. Tôi có nhiều thời gian, các cô gái."
L2_1.m_Talk_VTN = L3_1
L3_1 = "哈哈哈，当然可以了。我随时都有空的，美丽的小姐。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Haha, natürlich. Ich habe mehr als genug Zeit, meine Damen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Ha ha, bien sûr. J'ai tout le temps libre qu'il vous faut, mesdemoiselles."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 31611
