L3_1.m_Face = "UNIT_HATE"
L3_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "m_Crash"
L3_1[L4_1] = 20
L4_1 = "으으, 이 재수없어, 어제 먹은 점심이 올라올 것 같네."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "うぐっ、気持ち悪い。昨日食べた昼ごはん、戻しちゃいそう。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Ugh, gross. Yesterday's lunch is crawling back up my stomach."
L3_1.m_Talk_ENG = L4_1
L4_1 = "矮額！真噁心，我昨天吃的午飯都要吐出來了。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เอิ่ม จะอ๊วก มื้อเที่ยงเมื่อวานเริ่มรู้สึกคลื่นใส้ละสิ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ôi, ghê rợn quá. Bữa trưa hôm qua đang réo dạ dày của tôi."
L3_1.m_Talk_VTN = L4_1
L4_1 = "呕、呕！真恶心，感觉昨天吃的午饭都要吐出来了。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Urgh, einfach ekelhaft. Da kommt mir direkt das Mittagessen von gestern wieder hoch."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Ugh, ça me donne envie de rendre mon déjeuner de la veille..."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 31611
