L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L4_1.m_Pos = "C"
L5_1 = "그보다, 그 빨간 망토는 어디로 사라졌지?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "それより、あの赤ずきんはどこに消えたのかしら？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Anyway, where's Red Riding Hood?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "不過那個紅色披風到底去哪啦？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ว่าแต่หนูน้อยหมวกแดงเธออยู่ไหนแล้วล่ะ?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Dù sao đi nữa, Cô Bé Quàng Khăn Đỏ ở đâu?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "话说，那个红色披风到底去哪儿了？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Wo ist eigentlich das Rotkäppchen hin?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Bon, et sinon. Où est passé ce Petit chaperon rouge ?"
L4_1.m_Talk_FRA = L5_1
