L10_1 = "KYLE_DELTA_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "L"
L9_1.m_Pos = L10_1
L10_1 = "실비아의 리프노드의 위치를 조회하면…… 여기군."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "シルビアさんのリーフノードの位置を検索すると……ここか。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Tracking Sylvia and Leaf Node's location... leads to here."
L9_1.m_Talk_ENG = L10_1
L10_1 = "追蹤希爾維亞節點的位置……在這裡。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "การติดตามตำแหน่งของซิลเวียและลีฟโหนด... พาไปที่นี่"
L9_1.m_Talk_THA = L10_1
L10_1 = "Theo dõi vị trí của Sylvia và Nút Lá thì... dẫn đến đây."
L9_1.m_Talk_VTN = L10_1
L10_1 = "追踪希尔薇娅节点的位置……在这里。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Wenn ich Sylvias und Leaf Nodes Aufenthaltsort lokalisiere, dann führt es mich ... hierher."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Le suivi de la géolocalisation de Sylvia et Leaf Node... mène ici."
L9_1.m_Talk_FRA = L10_1
