L11_1 = "UNIT_SURPRISE"
L10_1.m_Face = L11_1
L11_1 = "KYLE_DELTA_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "L"
L10_1.m_Pos = L11_1
L11_1 = "m_Crash"
L10_1[L11_1] = 20
L11_1 = "그런데, 오싹오싹 고스트 하우스? 대령님과 실비아가 같이 담력 시험을……?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ゾクゾク・ゴーストハウス？　大佐とシルビアさんが一緒に肝試しを……？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "But, Creepy Ghost House? Is Colonel and Sylvia testing their courage here...?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "毛骨悚然鬼屋？上校和希爾維亞一起……參加試膽大會？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แต่ที่บ้านผีสิงน่าขนลุกนี่เหรอ? ผู้พันกับซิลเวียกำลังมาทดสอบความกล้าที่นี่หรือเปล่า...?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Nhưng, Ngôi Nhà Ma Ám Rùng Rợn? Có phải Đại tá và Sylvia đang thử lòng can đảm ở đây không...?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "毛骨悚然鬼屋？上校大人和希尔薇娅在一起……试胆吗？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Aber das ist doch ein gruseliges Geisterhaus?! Wollen der Oberst und Sylvia hier ihren Mut auf die Probe stellen ...?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "La Maison hantée de la peur...? Le colonel et Sylvia seraient-ils en train de mettre leur courage à l'épreuve dans un tel endroit...?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 31611
L11_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L11_1.m_bWaitClick = true
