L12_1 = "UNIT_DESPAIR"
L11_1.m_Face = L12_1
L12_1 = "KYLE_DELTA_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "L"
L11_1.m_Pos = L12_1
L12_1 = "m_Crash"
L11_1[L12_1] = 10
L12_1 = "무언가 이상해. 두 사람은 대체 나에게 뭘 숨기고 있는 거지?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "怪しい。二人はいったい僕に何を隠しているんだ？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Something seems off. What are those two hiding from me?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "有點奇怪。他們二個到底瞞著我什麼？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ดูเหมือนว่ามีบางอย่างแปลกๆ สองคนนั้นกำลังปิดบังอะไรผมอยู่?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Có vẻ không ổn. Hai người đó đang giấu mình gì đó?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "有点奇怪。他们两个到底在瞒着我做什么？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Irgendwas stimmt hier nicht. Was verbergen die beiden bloß vor mir?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "J'ai un mauvais pressentiment. J'ai l'impression que ces deux-là me cachent quelque chose."
L11_1.m_Talk_FRA = L12_1
