L13_1[L14_1] = 10
L14_1 = "이 축축한 안개…… 바스락 거리는 나뭇잎 소리…… 그리고 이 음산한 분위기……"
L13_1.m_Talk_KOREA = L14_1
L14_1 = 0.04
L13_1.m_fTalkTime = L14_1
L14_1 = "このジメジメした霧……乾いた音を立てる落ち葉……そして、この陰湿な雰囲気……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "The humid fog... the crisp sound of leaves... and this chilling atmosphere..."
L13_1.m_Talk_ENG = L14_1
L14_1 = "濕氣的霧……窸窸窣窣的樹葉聲……還有陰森的氛圍……"
L13_1.m_Talk_TWN = L14_1
L14_1 = "สายหมอก...เสียงใบไม้ร่วง...และบรรยากาศสุดชิวแบบนี้..."
L13_1.m_Talk_THA = L14_1
L14_1 = "Sương mù ẩm ướt... tiếng lá xào xạc... và bầu không khí lạnh lẽo này..."
L13_1.m_Talk_VTN = L14_1
L14_1 = "潮湿的雾……沙沙作响的树叶声……还有阴森的氛围……"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Dieser feuchte Nebel ... das Rascheln der Blätter ... und diese düstere Atmosphäre ..."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Le brouillard humide... le craquement des feuilles... et cette atmosphère effrayante..."
L13_1.m_Talk_FRA = L14_1
