L14_1.m_CharStrID = L15_1
L15_1 = "R"
L14_1.m_Pos = L15_1
L15_1 = "몇 번을 봐도 믿을 수 없어……. 이게 다 시뮬레이션일 뿐이라고?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "何度見ても信じられない……これが全部シミュレーション？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "No matter how many times I see it, I still can't believe this is all just a simulation..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "不管看多少次都難以置信……這些真的都只是模擬？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ดูยังไงก็ไม่อยากเชื่อเลยว่าทั้งหมดนี้เป็นเพียงการจำลอง..."
L14_1.m_Talk_THA = L15_1
L15_1 = "Dù có xem bao nhiêu lần đi chăng nữa, tôi vẫn không thể tin rằng tất cả chỉ là mô phỏng…"
L14_1.m_Talk_VTN = L15_1
L15_1 = "无论看多少次都难以置信……这些真的都只是模拟？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Egal, wie oft ich es mir auch ansehe, ich kann immer noch nicht glauben, dass das alles nur eine Simulation ist ..."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Peu importe le nombre de fois où j'en fais l'expérience... Je n'arrive toujours pas à croire qu'il s'agit d'une simulation."
L14_1.m_Talk_FRA = L15_1
