L17_1 = "틀렸어. 내 능력으로도 이곳의 원리를 완벽히는 파악할 수 없어."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ダメだわ。私の能力でもここの原理を完璧には把握できない。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "This is hopeless. I can't fully comprehend how this place works, even with my abilities."
L16_1.m_Talk_ENG = L17_1
L17_1 = "糟糕，以我的能力無法完全掌握這裡的原理。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "น่าเสียดาย ฉันไม่เข้าใจว่าโลกนี้ทำได้ยังไง แม้ฉันจะมีความสามารถก็ตาม"
L16_1.m_Talk_THA = L17_1
L17_1 = "Thật vô vọng. Tôi không thể hiểu hết cách thế giới này vận hành, ngay cả với khả năng của tôi."
L16_1.m_Talk_VTN = L17_1
L17_1 = "糟了，凭我的能力无法完全掌握这里的原理。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich bin total aufgeschmissen. Trotz meiner Fähigkeiten kann ich die Prinzipien dieses Ortes nicht vollständig verstehen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "C'est sans espoir. Je n'arrive pas à comprendre comment cet endroit fonctionne, même avec mes capacités."
L16_1.m_Talk_FRA = L17_1
