L27_1 = 40
L25_1[L26_1] = L27_1
L26_1 = "뭡니까, 당신!? 또 이쪽 세계에 무슨 민폐를 끼치러 온 겁니까?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "何ですか、あなた！！　またこちらの世界に迷惑をかけに来たのですか？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "What are you doing here?! What trouble are you causing this world now?!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "你想做什麼？！你來這個世界又想搞什麼鬼？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "นายมาทำอะไรที่นี่?!  นายสร้างปัญหาอะไรให้กับโลกนี้อยู่หรือปล่าวน่ะ?!"
L25_1.m_Talk_THA = L26_1
L26_1 = "Cô đang làm gì ở đây?! Giờ cô đang gây ra rắc rối gì cho thế giới này thế?!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "你想做什么？！你来这个世界又想策划什么？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Was machst du hier?! Hast du etwa vor, auch in dieser Welt für Ärger zu sorgen?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Que faites-vous ici ?! Êtes-vous venue dans ce monde pour causer des problèmes à nouveau ?"
L25_1.m_Talk_FRA = L26_1
