L27_1 = "설마, 이번에도 침식체를 유기하러 온 겁니까?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "まさか、今回も侵食体を捨てに？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Are you here to dispose of more C.O.s?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "難道是想把更多侵蝕體丟過來嗎！？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เธอล่ะมาที่นี่เพื่อกำจัดวัตถุคอรัปต์ชั่นที่เพิ่มขึ้นหรอ?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Cô đến đây để xử lý thêm V.T.A.M. à?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "难道是想把更多侵蚀体丢过来吗！？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Bist du etwa wieder hier, um noch mehr C.°O.s zu entsorgen?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Êtes-vous ici pour y abandonner des O.C., comme l'autre fois ?"
