L28_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_HATE"
L29_1 = "FX_CUTSCEN_NOISE_RUSTLE_04"
L28_1.m_StartFXSoundName = L29_1
L29_1 = "KYLE_DELTA_APHALLOWEEN_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "R_M_I"
L28_1.m_Pos = L29_1
L29_1 = "뭔가요, 당신!? 왜 군인이 근무 시간에 여기 있는 거죠?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "何ですか、あなた！！　なぜ軍人が勤務時間にここにいるのですか？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "What are YOU doing here?! What is a soldier doing here during work hours?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "你怎麼回事？！你一個軍人，上班時間為什麼會在這裡？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "นายมาทำอะไรที่นี่?! เป็นทหารออกมาที่นี่นอกเวลางานได้ไง?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Cậu đang làm gì ở đây?! Một người lính làm gì ở đây trong giờ làm việc?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "你怎么回事？！你一个军人，上班时间为什么会在这里？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Was machst du überhaupt hier?! Was macht ein Soldat hier während seiner regulären Arbeitszeit?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Qu'est-ce que VOUS faites ici ?! Un soldat, pendant les heures de travail ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_1@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
