L30_1 = "UNIT_LAUGH"
L29_1.m_Face = L30_1
L30_1 = "KYLE_DELTA_APHALLOWEEN_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "R"
L29_1.m_Pos = L30_1
