L31_1 = 40
L29_1[L30_1] = L31_1
L30_1 = "명예로운 델타 세븐 요원이 근무 시간에 땡땡이를 치다니, 당신네 델타 세븐은 기강이 참 해이하군요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "名誉あるデルタセブンの一員が勤務時間にサボるなんて、そちらのデルタセブンは規律が乱れきっていますね。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "An honorable member of the Delta Seven, playing hooky during work hours. You Delta Sevens lack discipline, it seems."
L29_1.m_Talk_ENG = L30_1
L30_1 = "榮耀的第七三角洲部隊成員居然在上班時間偷懶，這個世界的第七三角洲部隊真是紀律渙散！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "สมาชิคกิตติมศักดิ์ของเดลต้าเซเว่น ชอบแอบออกมาเล่นในเวลาทำงาน ดูเหมือนว่านายกำลังขาดระเบียบวินัยของเดลต้าเซเว่นอยู่นะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Một thành viên vinh dự của Delta Seven lại chơi bời trong giờ làm việc. Có vẻ như Delta Sevens của các cậu thật thiếu kỷ luật."
L29_1.m_Talk_VTN = L30_1
L30_1 = "光荣的德尔塔部队要员居然在上班时间偷懒，这个世界的德尔塔部队纪律真是涣散！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ein ehrenwertes Mitglied der Delta Seven, das sich während seiner Schicht vor seinen Aufgaben drückt. Euch Delta Seven Typen mangelt es anscheinend echt an Disziplin."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Un membre honorable du Delta Seven, qui se tourne les pouces pendant les heures de travail. Vous manquez vraiment de discipline au Delta Seven, on dirait."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
