L32_1 = "m_Crash"
L31_1[L32_1] = 25
L32_1 = "하! 군인에 어울리지 않는 건 그쪽도 만만치 않을 텐데요?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "は！　軍人に相応しくないという点では、そちらも負けていないと思いますが。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Hah! Look who's talking about soldiers and discipline."
L31_1.m_Talk_ENG = L32_1
L32_1 = "蛤！你也好不到哪去吧？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฮ่า! ดูสิว่าใครกำลังพูดถึงทหารและระเบียบวินัยอยู่"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ha! Hãy nhìn xem ai đang nói về người lính và kỷ luật kìa."
L31_1.m_Talk_VTN = L32_1
L32_1 = "哈！你也好不到哪里去啊？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ha! Fass dir mal an deine eigene Nase! Gerade du solltest nicht über die Disziplin eines Soldaten urteilen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Ha ! Vous osez me parler de soldats et de discipline."
L31_1.m_Talk_FRA = L32_1
