L33_1 = "UNIT_SERIOUS"
L32_1.m_Face = L33_1
L33_1 = "KYLE_DELTA_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "L"
L32_1.m_Pos = L33_1
L33_1 = "m_Crash"
L34_1 = 50
L32_1[L33_1] = L34_1
L33_1 = "그 파렴치한 복장으로 군의 기강을 논하는 게 설득력이 있다고 생각하십니까?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "その破廉恥な服装で軍の規律を論ずるとは、説得力があると思っているのですか？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Do you really think your words carry any weight while wearing that vulgar costume?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "穿著那一身羞恥的衣服討論部隊紀律，你覺得有說服力嗎？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เธอคิดว่าคำพูดของเธอจะดูน่าเชื่อถือหรอ ดูสิเธอสวมชุดบ้าๆนี้มาได้ไง?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cô có thực sự nghĩ lời nói của mình có trọng lượng khi mặc trang phục thô tục đó không?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "穿着那一身恬不知耻的衣服讨论部队纪律，你觉得有说服力吗？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Hältst du es wirklich für überzeugend, über militärische Disziplin in diesem schamlosen Outfit zu diskutieren?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Pensez-vous vraiment que vos mots ont du poids alors que vous portez ce costume vulgaire ?"
L32_1.m_Talk_FRA = L33_1
