L34_1[L35_1] = 25
L35_1 = "흥! 아무것도 모르면서 비웃지 마시죠!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "フン！　何も知らないくせに、笑わないでください！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Hmph! Don't mock me when you don't know the context."
L34_1.m_Talk_ENG = L35_1
L35_1 = "哼！你什麼都不不知道，少在那邊指指點點！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ฮึ่ม! เฮ้ อย่ามาล้อเลียนฉันนะหากนายไม่รู้ความจริงสักหน่อย"
L34_1.m_Talk_THA = L35_1
L35_1 = "Hừm! Đừng chế nhạo tôi khi cậu không biết hoàn cảnh."
L34_1.m_Talk_VTN = L35_1
L35_1 = "哼！明明什么都不懂，就不要嘲笑我了！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Hmpf! Du hast doch überhaupt keine Ahnung, also lach mich gefälligst nicht aus!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Hmph ! Ne vous moquez pas de moi alors que vous ne connaissez pas le contexte."
L34_1.m_Talk_FRA = L35_1
