L37_1 = 50
L35_1[L36_1] = L37_1
L36_1 = "뭐, 뭔가 조금 잘 못되긴 했지만……. 이게 다 우리 세계를 위해서 이렇게 된 거라고요!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "し、少々手違いがありはしましたけど……これも全部、私たちの世界のためなんです！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Th-things took a weird turn, but... all of this is for our world!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "雖， 雖說是有哪裡不太對勁……但這全都是為了我們的世界！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ทุกสิ่งเปลี่ยนแปลงอย่างมหัศจรรย์ แต่... ทั้งหมดนี้ก็เพื่อโลกของเรา!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Mọi chuyện đã diễn ra một cách kỳ lạ, nhưng... tất cả những điều này là vì thế giới của chúng tôi!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "虽、虽说有点不太对……但这都是为了我们世界才这样的！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Die Dinge scheinen ein wenig schiefgelaufen zu sein, aber ... das ist alles zugunsten unserer Welt!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Les choses ont pris une tournure étrange, mais... tout ça, c'est pour le bien de notre monde !"
L35_1.m_Talk_FRA = L36_1
