L38_1 = "그런 복장으로…… 세계를 위한다고요!?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "そんな服装で……世界のため！？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "For your world... in that outfit?!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "你說你穿成這樣……是為了世界？！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เพื่อโลกของเธอ...ในชุดบ้าๆนี่นะ?!"
L37_1.m_Talk_THA = L38_1
L38_1 = "Vì thế giới của cô... trong bộ trang phục đó?!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "你这一身穿着……竟然说是为了世界？！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Zugunsten deiner Welt ... in diesem Outfit?!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Vous agissez pour le bien du monde... dans cette tenue ?!"
L37_1.m_Talk_FRA = L38_1
