L42_1 = 50
L40_1[L41_1] = L42_1
L41_1 = "왜 갑자기 그렇게 뚫어져라 쳐다보시는 거죠!? 기분 나쁘게!!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "どうして急にじっと見るのですか！？　気持ち悪いです！！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Why are you staring so intensely all of a sudden!? It's creepy!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "為什麼突然那樣盯著我看？！感覺很奇怪！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ทำไมจู่ๆ นายถึงได้จ้องมองฉันอย่างเข้มงวดขนาดนี้!? เห็นแล้วมันน่าขนลุกซะมัด!"
L40_1.m_Talk_THA = L41_1
L41_1 = "Sao đột nhiên cậu lại nhìn chăm chằm thế!? Thật ghê sợ!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "为什么突然那么盯着我看？！感觉很奇怪！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Warum siehst du mich plötzlich mit diesem stechenden Blick an!? Da bekomme ich ja Angst!!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Pourquoi est-ce que vous me scrutez de haut en bas tout à coup ?! Vous me mettez mal à l'aise !"
L40_1.m_Talk_FRA = L41_1
