L44_1 = 40
L42_1[L43_1] = L44_1
L43_1 = "아니! 그쪽이 그런 파렴치한 복장을 입고 있으니까 볼 수밖에 없는 거 아닙니까!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "いや！　そちらがそういった破廉恥な服を着ているので、見るしかないではないですか！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I mean! It's your fault for wearing something so vulgar!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "拜託！你穿成這樣，我有可能不看嗎！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ผมหมายถึง! มันเป็นความผิดพลาดของเธอตางหากที่ใส่ชุดนี้มางานนี่!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ý tôi là! Đó là lỗi của cô khi mặc thứ gì đó thô tục như thế!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "不是！谁叫你穿着那种恬不知耻的衣服，那我还不能看了！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hör mal! Ich konnte halt nicht anders, als mir dein schamloses Outfit anzusehen!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Non mais, c'est de votre faute si vous portez une tenue aussi indécente !"
L42_1.m_Talk_FRA = L43_1
