L44_1 = "경고했습니다! 이쪽 보지 마세요!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "警告しました！　こちらを見ないでください！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I'm warning you! Stop looking at me!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "我警告你喔！不准看我！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "นี่ฉันขอเตือนนายไว้ก่อนนะ! เลิกมองฉันแบบนี้สักที!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi cảnh báo cậu! Đừng nhìn tôi!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "我警告你！不要往这边看！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich warne dich! Hör auf, mich so anzustarren!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je vous préviens ! Arrêtez de me regarder !"
L43_1.m_Talk_FRA = L44_1
